export function normalizeArabic(text) {
  if (!text) return '';
  return String(text)
    .replace(/\u0670/g, 'ا')
    .replace(/[\u0617-\u061A\u064B-\u065F\u06D6-\u06ED]/g, '')
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ـ/g, '')
    .replace(/ة/g, 'ه')
    .replace(/[ؤ]/g, 'و')
    .replace(/[ئ]/g, 'ي')
    .replace(/\s+/g, ' ')
    .trim();
}

export function getNormalizedChar(c) {
  let n = c;
  n = n.replace(/\u0670/g, 'ا');
  n = n.replace(/[\u0617-\u061A\u064B-\u065F\u06D6-\u06ED]/g, '');
  n = n.replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g, '');
  n = n.replace(/[أإآٱ]/g, 'ا');
  n = n.replace(/ى/g, 'ي');
  n = n.replace(/ـ/g, '');
  n = n.replace(/ة/g, 'ه');
  n = n.replace(/[ؤ]/g, 'و');
  n = n.replace(/[ئ]/g, 'ي');
  return n;
}

export async function loadQuran() {
  if (quranVerses) return quranVerses;
  try {
    const a = versesData;          /* verses.json */
    const b = versesCleanData;     /* verses_no_tashkeel.json */

    if (!Array.isArray(a) || !Array.isArray(b)) {
      throw new Error('أحد ملفي الآيات ليس قائمة صحيحة');
    }
    if (a.length !== 6236 || b.length !== 6236) {
      throw new Error(`عدد الآيات غير صحيح: ${a.length} / ${b.length}`);
    }

    /* ===== اكتشاف تلقائي: المشكلة للعرض، والمضمونة للبحث ===== */
    const TASHKEEL = /[\u064B-\u065F\u0670\u06D6-\u06ED]/;
    const decorScore = (arr) => {
      let score = 0;
      [0, 250, 1000, 3000, 6000].forEach(i => {
        const t = (arr[i] && arr[i].text_ar) || '';
        if (TASHKEEL.test(t)) score++;
      });
      return score;
    };
    const aDec = decorScore(a);
    const bDec = decorScore(b);

    let displayData, searchData;
    if (aDec >= bDec) { displayData = a; searchData = b; }
    else              { displayData = b; searchData = a; }

    quranVerses = displayData;                       /* المزخرفة → العرض */
    quranCleanVerses = searchData;                   /* المضمونة → البحث */
    quranCleanNorm = searchData.map(v => normalizeArabic(v.text_ar));
	
	/// new
	
	    quranCleanFullText = quranCleanNorm.join(' ');
	
	///////////

    console.log('📖 نسخة العرض (المزخرفة):', (displayData[0].text_ar || '').slice(0, 60));
    console.log('🔍 نسخة البحث (المضمونة):', (searchData[0].text_ar || '').slice(0, 60));
    console.log(`تم تحميل القرآن: ${quranVerses.length} آية — البحث على المضمونة والعرض بالمزخرفة`);
    return quranVerses;
  } catch (error) {
    console.error('خطأ أثناء تحميل القرآن:', error);
    quranVerses = null;
    throw error;
  }
}

export function getAyahInfo(ayahId) {
  if (!Number.isInteger(ayahId) || ayahId < 1 || ayahId > 6236) return null;
  if (!quranVerses) return null;
  const verse = quranVerses[ayahId - 1];
  if (!verse) return null;
  const surahNumber = verse.surah_number;
  const surahName = surahNames[surahNumber - 1] || `السورة ${surahNumber}`;
  const makki = surahMakki[surahNumber - 1];
  return {
    ayahId,
    surahNumber,
    surahName,
    ayahNumber: verse.ayahNumber,
    pageNumber: verse.page,
    juzNumber: verse.juz,
    revelation: makki === true ? 'مكية' : 'مدنية'
  };
}

function countMatches(text, regex) {
  regex.lastIndex = 0;
  const matches = text.match(regex);
  return matches ? matches.length : 0;
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function countWholeWord(text, word) {
  const re = new RegExp(escapeRegex(word) + '(?=\\s|$)', 'g');
  let count = 0;
  let m;
  while ((m = re.exec(text)) !== null) {
    if (m.index === 0 || /\s/.test(text[m.index - 1])) count++;
    if (m.index === re.lastIndex) re.lastIndex++;
  }
  return count;
}

function stripWa(w) {
  return (w.startsWith('و') && w.length > 2) ? w.slice(1) : w;
}

function stemArabic(word) {
  if (!word || word.length < 3) return word;
  let w = word;
  const prefixes = ['وال', 'فال', 'بال', 'كال', 'لل', 'وس', 'فس', 'بس', 'كس', 'لس', 'وا', 'فا', 'با', 'كا', 'لا', 'سا', 'و', 'ف', 'ب', 'ك', 'ل', 'س', 'ا'];
  for (const p of prefixes) {
    if (w.startsWith(p) && w.length > p.length + 2) {
      w = w.slice(p.length);
      break;
    }
  }
  const suffixes = ['كموها', 'تموها', 'هما', 'كما', 'كم', 'تم', 'هن', 'كن', 'ها', 'هم', 'نا', 'ني', 'وا', 'تا', 'ين', 'ون', 'ة', 'ه', 'ك', 'ت', 'ا', 'ي', 'ن'];
  for (const s of suffixes) {
    if (w.endsWith(s) && w.length > s.length + 2) {
      w = w.slice(0, -s.length);
      break;
    }
  }
  if (w.startsWith('ال') && w.length > 4) {
    w = w.slice(2);
  }
  return w.length >= 2 ? w : word;
}

