 "وَيَسْتَخْلِفُ": "يَاتِي بِقَوْمٍ آخَرِينَ يَخْلُفُونَكُمْ فِي دِيَارِكُمْ",
 "حَفِيظٌ": "رَقِيبٌ عَتِيدٌ",
 "غَلِيظٍ": "شَدِيدٍ",
 "جَبَّارٍ": "مُسْتَكْبِرٍ",
 "عَنِيدٍ": "لَا يَقْبَلُ الحَقَّ",
 "أَنشَأَكُمْ": "أَوْجَدَكُمْ",
 "وَاسْتَعْمَرَكُمْ فِيهَا": "جَعَلَكُمْ عُمَّارًا لَهَا",
 "كُنتَ فِينَا مَرْجُوًّا": "كُنَّا نَرْجُو أَنْ تَكُونَ سَيِّدًا",
 "مُرِيبٍ": "مُوقِعٍ فِي الرِّيبَةِ، وَالاِخْتِلَافِ المَذْمُومِ",
 "تَخْسِيرٍ": "تَضْلِيلٍ، وَإِبْعَادٍ عَنِ الخَيْرِ",
 "بِسُوءٍ": "بِنَحْرٍ أَوْ ضَرْبٍ",
 "فَعَقَرُوهَا": "فَنَحَرُوهَا",
 "تَمَتَّعُوا فِي دَارِكُمْ": "اسْتَمْتِعُوا بِحَيَاتِكُمْ فِي بَلَدِكُمْ",
 "خِزْيِ يَوْمِئِذٍ": "هَوَانِ ذَلِكَ اليَوْمِ، وَذِلَّتِهِ",
 "الصَّيْحَةُ": "صَوْتٌ مِنَ السَّمَاءِ مُهْلِكٌ",
 "حَنِيذٍ": "مَشْوِيٍّ بِالحِجَارَةِ المُحْمَاةِ",
 "نَكِرَهُمْ": "أَنْكَرَ ذَلِكَ مِنْهُمْ",
 "وَأَوْجَسَ مِنْهُمْ خِيفَةً": "أَحَسَّ فيِ نَفْسِهِ خَوْفًا مِنْهُمْ",
 "وَمِن وَرَاءِ": "وَمِنْ بَعْدِ",
 "يَا وَيْلَتَى": "كَلِمَةُ تَعَجُّبٍ",
 "بَعْلِي": "زَوْجِي",
 "حَمِيدٌ": "مَحْمُودُ الصِّفَاتِ وَالأَفْعَالِ",
 "مَّجِيدٌ": "ذُو عَظَمَةٍ",
 "الرَّوْعُ": "الخَوْفُ",
 "أَوَّاهٌ": "كَثِيرُ التَّضَرُّعِ وَالدُّعَاءِ",
 "مُّنِيبٌ": "تَائِبٌ يَرْجِعُ إِلَى اللهِ فِي أُمُورِهِ كُلِّهَا",
 "سِيءَ بِهِمْ": "سَاءَهُ مَجِيئُهُمْ خَوْفًا عَلَيْهِمْ مِنْ قَوْمِهِ أَنْ يَفْعَلُوا بِهِمُ الفَاحِشَةَ",
 "وَضَاقَ بِهِمْ ذَرْعًا": "ضَاقَ صَدْرُهُ، وَحَزِنَ خَوْفًا عَلَيْهِمْ",
 "عَصِيبٌ": "شَدِيدٌ",
 "يُهْرَعُونَ": "يُسْرِعُونَ فِي مُتَابَعَتِهِمْ عَلَى الضَّلَالِ",
 "وَلَا تُخْزُونِ": "لَا تَفْضَحُونِي",
 "رَّشِيدٌ": "يَامُرُ بِالمَعْرُوفِ، وَيَنْهَى عَنِ المُنْكَرِ",
 "مِنْ حَقٍّ": "مِنْ حَاجَةٍ، أَوْ رَغْبَةٍ",
 "فَأَسْرِ": "فَاخْرُجْ",
 "بِقِطْعٍ مِّنَ اللَّيْلِ": "بِبَقِيَّةٍ مِنَ اللَّيْلِ",
 "سِجِّيلٍ": "طِينٍ مُتَحَجِّرٍ",
 "مَّنضُودٍ": "صُفَّ بَعْضُهَا إِلَى بَعْضٍ مُتَتَابِعَةً",
 "مُّسَوَّمَةً": "مُعَلَّمَةً عِنْدَ اللهِ بِعَلَامَةٍ مَعْرُوفُةٍ لَا تُشْبِهُ حِجَارَةَ الأَرْضِ",
 "بَقِيَّةُ اللهِ": "مَا يُبْقِي اللهُ لَكُمْ بَعْدَ إِيفَاءِ الكَيْلِ وَالمِيزَانِ مِنَ الرِّبْحِ الحَلَالِ",
 "بِحَفِيظٍ": "رَقِيبٍ أُحْصِي أَعْمَالَكُمْ",
