 "لَا يَجْرِمَنَّكُمْ": "لَا يَحْمِلَنَّكُمْ",
 "شِقَاقِي": "عَدَاوَتِي",
 "رَهْطُكَ": "عَشِيرَتُكَ",
 "بِعَزِيزٍ": "بِصَاحِبِ قَدْرٍ وَمَنْزِلَةٍ",
 "وَرَاءَكُمْ ظِهْرِيًّا": "مَنْبُوذًا خَلْفَ ظُهُورِكُمْ",
 "وَسُلْطَانٍ مُّبِينٍ": "حُجَّةٍ بَيِّنَةٍ عَلَى صِدْقِهِ",
 "فَأَوْرَدَهُمُ": "فَأَدْخَلَهُمْ",
 "الْوِرْدُ": "المَدْخَلُ",
 "الْمَوْرُودُ": "المَدْخُولُ فِيهِ، وَهُوَ هُنَا النَّارُ",
 "الرِّفْدُ": "العَوْنُ، وَالعَطَاءُ",
 "الْمَرْفُودُ": "المُعْطَى لَهُمْ",
 "قَائِمٌ": "آثَارُهُ بَاقِيَةٌ كَمَدَائِنِ صَالِح",
 "وَحَصِيدٌ": "مَحْصُودٌ قَدْ مُحِيَتْ آثَارُهُ، وَلَمْ يَبْقَ مِنْهُ شَيْءٌ",
 "أَغْنَتْ": "نَفَعَتْ",
 "تَتْبِيبٍ": "تَدْمِيرٍ، وَإِهْلَاكٍ، وَخُسْرَانٍ",
 "زَفِيرٌ": "تَنَفُّسٌ شَدِيدٌ تَنْتَفِخُ مِنْهُ الضُّلُوعُ يَدُلُّ عَلَى شِدَّةِ عَذَابِهِمْ",
 "وَشَهِيقٌ": "صَوْتٌ شَنِيعٌ، يُسْمَعُ عِنْدَ إِدْخَالِ النَّفَسِ",
 "مَجْذُوذٍ": "مَقْطُوعٍ",
 "وَلَا تَطْغَوْا": "لَا تَتَجَاوَزُوا مَا حَدَّهُ اللهُ لَكُمْ",
 "وَلَا تَرْكَنُوا": "لَا تَمِيلُوا",
 "طَرَفَيِ النَّهَارِ": "الصَّبَاحَ وَالمَسَاءَ، وقِيلَ: المُرَادُ بِهَا: صَلَاةُ الفَجْرِ وَالظُّهْرِ وَالعَصْرِ",
 "وَزُلَفًا مِّنَ اللَّيْلِ": "سَاعَاتٍ مِنَ اللَّيْلِ، وقِيلَ: المُرَادُ بِهَا: المَغْرِبُ وَالعِشَاءُ، أَوِ العِشَاءُ وَحْدَهَا",
 "الْقُرُونِ": "الأُمَمِ السَّابِقَةِ",
 "أُوْلُوا بَقِيَّةٍ": "بَقَايَا مِنْ أَهْلِ الخَيْرِ وَالصَّلَاحِ",
