 "اشْدُدْ بِهِ أَزْرِي": "قَوِّنِي بِهِ، وَشُدَّ بِهِ ظَهْرِي",
 "أَمْرِي": "النُّبُوَّةِ",
 "يَكْفُلُهُ": "يُرَبِّيهِ، وَيُرْضِعُهُ",
 "تَقَرَّ عَيْنُهَا": "تَطِيبُ نَفْسُهَا",
 "وَفَتَنَّاكَ فُتُونًا": "ابْتَلَيْنَاكَ ابْتِلَاءً",
 "عَلَى قَدَرٍ": "عَلَى وَفْقِ الوَقْتِ المُقَدَّرِ لِإرْسَالِكَ",
 "وَاصْطَنَعْتُكَ لِنَفْسِي": "اصْطَفَيْتُكَ لِرِسَالَتِي",
 "وَلَا تَنِيَا": "لَا تَفْتُرَا وَلَا تَضْعُفَا",
 "يَفْرُطَ عَلَيْنَا": "يُعَاجِلَنَا بِالعُقُوبَةِ",
 "خَلْقَهُ": "صُورَتَهُ اللَّائِقَةَ بِخَاصَّتِهِ وَمَنْفَعَتِهِ",
 "الْقُرُونِ الْأُولَى": "الأُمَمِ المَاضِيَةِ",
 "مَهْدًا": "فِرَاشًا مُمَهَّدًا",
 "سُبُلًا": "طُرُقًا",
