/* بناء الفهرس: المفتاح الأخير يفوز (ليصحّح أي مفتاح مكرر قديم) */
const MEANING_INDEX = {};
Object.keys(RAW_MEANINGS).forEach(k => {
  MEANING_INDEX[normalizeArabic(k)] = { display: k, meaning: RAW_MEANINGS[k] };
});

/* بادئات ولواحق العربية للتفكيك الصرفي */
const WORD_PREFIXES = ['', 'و','ف','ب','ك','ل','س','م','ال','وال','فال','بال','كال','لل','وس','فس','بس','كس','لس','وا','فا','با','كا','لا','سا','ا','ي','ت','ن','است','يست','تست','نست'];
const WORD_SUFFIXES = ['', 'ون','ين','ات','ان','وا','تا','كم','هم','هن','كن','نا','ني','ها','ه','ك','ت','ا','ي','ن','ة','هما','كما','تم','ناهم','تهم','كموا','تموه'];

function middleForms(form) {
  const set = [];
  for (const p of WORD_PREFIXES) {
    if (p && form.indexOf(p) !== 0) continue;
    const rest = form.slice(p.length);
    for (const s of WORD_SUFFIXES) {
      if (s && rest.slice(rest.length - s.length) !== s) continue;
      const mid = s ? rest.slice(0, rest.length - s.length) : rest;
      if (mid.length >= 2 && set.indexOf(mid) === -1) set.push(mid);
    }
  }
  set.sort((a, b) => b.length - a.length);
  return set;
}

export function getWordMeaning(word) {
  if (!word || !word.trim()) return null;

  const base = word.trim()
    .replace(/[\u064B-\u065F\u06D6-\u06ED\u0617-\u061A]/g, '')
    .replace(/[﴿﴾۝۞\uFD3E\uFD3F\u0640]/g, '');

  const form1 = normalizeArabic(base);
  const form2 = normalizeArabic(base.replace(/\u0670/g, ''));

  /* الحروف المقطعة: مطابقة تامة */
  for (const key of EXACT_KEYS) {
    if (form1 === key || form2 === key) return EXACT_INDEX[key];
  }

  /* التفكيك الصرفي: بادئة + جذع + لاحقة */
  const mids = middleForms(form1);
  middleForms(form2).forEach(m => { if (mids.indexOf(m) === -1) mids.push(m); });

  for (const mid of mids) {
    if (MEANING_INDEX[mid]) {
      console.log('نقرة:', word, '→ الجذر المطابق:', mid);
      return MEANING_INDEX[mid];
    }
  }
  console.log('نقرة:', word, '→ جذوعها:', mids.join('، '), '→ لا معنى');
  return null;
}

function expandMergedTerms(terms) {
  if (!quranCleanFullText) return terms;
  
  const expandOne = (term) => {
    // 1. تطبيع الكلمة للبحث عنها بدقة
    const normTerm = normalizeArabic(term);
    if (quranCleanFullText.includes(normTerm)) return [term];
    
    // 2. محاولة التقسيم
    for (let i = 2; i <= normTerm.length - 2; i++) {
      const p1 = normTerm.substring(0, i);
      const p2 = normTerm.substring(i);
      
      if (p1.length >= 2 && p2.length >= 2 &&
          quranCleanFullText.includes(p1) && quranCleanFullText.includes(p2)) {
        // نرجع الأجزاء من الكلمة الأصلية للحفاظ على أي تشكيل إن وجد
        return [term.substring(0, i)].concat(expandOne(term.substring(i)));
      }
    }
    return [term];
  };

  let expanded = [];
  terms.forEach(t => { expanded = expanded.concat(expandOne(t)); });
  return expanded;
}
 
 /////
 
 export async function searchInQuran(searchWord, isExactMatch = false) {
  try {
    await loadQuran();
    const normalizedSearch = normalizeArabic(searchWord);
  //  const terms = normalizedSearch.split(/\s+/).filter(Boolean);
    
	// new new
	
	let terms = normalizedSearch.split(/\s+/).filter(Boolean);
    terms = expandMergedTerms(terms);   /* تفكيك الملتصق */
	
	////
	
    const results = [];
    let totalCount = 0;
    const termTotals = {};
    terms.forEach(t => { termTotals[t] = 0; });

    /* 1. جمع النتائج (البحث المرن OR - لم يتغير) */
    for (let i = 0; i < quranVerses.length; i++) {
      const displayVerse = quranVerses[i];
      const cleanVerse = quranCleanVerses[i];
      const normalizedVerse = quranCleanNorm[i];
      if (terms.length === 0 || !normalizedVerse) continue;

      let verseCount = 0;
      for (const term of terms) {
        const key = stripWa(term);
        let c = 0;
        if (isExactMatch) {
	    //if (isExactMatch || term.length <= 2) {		
          c = countWholeWord(normalizedVerse, key) + countWholeWord(normalizedVerse, 'و' + key);
        } else {
          c = countMatches(normalizedVerse, new RegExp(escapeRegex(term), 'g'));
          if (key !== term) c += countWholeWord(normalizedVerse, key);
        }
        if (c > 0) {
          termTotals[term] += c;
          verseCount += c;
        }
      }
      
      if (verseCount === 0) continue;

      const ayahId = i + 1;
      const ayahInfo = getAyahInfo(ayahId);
      if (!ayahInfo) continue;

      results.push({
        text: displayVerse.text_ar,
        cleanText: cleanVerse.text_ar,
        verseNumber: ayahId,
        ayahNumber: ayahInfo.ayahNumber,
        surahNumber: ayahInfo.surahNumber,
        surahName: ayahInfo.surahName,
        pageNumber: ayahInfo.pageNumber,
        juzNumber: ayahInfo.juzNumber,
        revelation: ayahInfo.revelation,
        count: verseCount
      });
      totalCount += verseCount;
    }

    /* 2. محرك الترتيب الذكي الجديد (التغيير الوحيد هنا) */
    results.forEach(r => {
      const nv = normalizeArabic(r.cleanText);
      let rank = 0;

      // أولوية 40: العبارة الكاملة موجودة تماماً (مثل: محمد رسول الله)
      if (nv.includes(normalizedSearch)) {
        rank += 40;
      }

      // أولوية 30: الآية تبدأ بأول كلمة بحث (مثل: قل، يا أيها)
      if (terms.length > 0) {
        const firstTerm = terms[0];
        const startForms = [firstTerm, 'و' + firstTerm, 'ف' + firstTerm, 'ب' + firstTerm, 'ك' + firstTerm, 'ل' + firstTerm];
        if (startForms.some(f => nv.startsWith(f))) {
          rank += 30;
        }
      }

      // أولوية 20: الآية تحتوي على كل كلمات البحث (حتى لو البحث مرن)
      if (terms.length > 1 && terms.every(t => nv.includes(t))) {
        rank += 20;
      }

      r._rank = rank;
    });

    // الترتيب: الأعلى نقاطاً أولاً، ثم ترتيب المصحف
    results.sort((a, b) => {
      if (b._rank !== a._rank) return b._rank - a._rank;
      return a.verseNumber - b.verseNumber;
    });
    results.forEach(r => delete r._rank);

    /* 3. الكلمات المتجاهلة */
 //   const ignored = terms.filter(t => termTotals[t] === 0);
    // return { count: totalCount, verses: results, ignored, error: null };
	
	/// new new
	
	const ignored = terms.filter(t => termTotals[t] === 0);
    return { count: totalCount, verses: results, ignored, termsUsed: terms, error: null };
	
	////
	
	
  } catch (error) {
    console.error('خطأ في البحث:', error);
    return { count: 0, verses: [], ignored: [], error: error.message || 'حدث خطأ' };
  }
}
 
 
/* ============================================================
 * البحث بالموضوع
 * ============================================================ */
export async function searchByTopic(topicKey) {
  try {
    await loadQuran();
    const topic = topicsData.find(t => t.key === topicKey);
    if (!topic || !Array.isArray(topic.keywords)) {
      return { count: 0, verses: [], ignored: [], error: 'الموضوع غير موجود' };
    }
    const results = [];
    let totalCount = 0;
    const ignored = [];

    for (let i = 0; i < quranVerses.length; i++) {
      const displayVerse = quranVerses[i];
      const cleanVerse = quranCleanVerses[i];
      const normalizedVerse = quranCleanNorm[i];
      if (!normalizedVerse) continue;

      let count = 0;
      for (const keyword of topic.keywords) {
        const nk = normalizeArabic(keyword);
        if (!nk) continue;
        count += countMatches(normalizedVerse, new RegExp(escapeRegex(nk), 'g'));
      }
      if (count === 0) continue;

      const ayahId = i + 1;
      const ayahInfo = getAyahInfo(ayahId);
      if (!ayahInfo) continue;

      results.push({
        text: displayVerse.text_ar,
        cleanText: cleanVerse.text_ar,
        verseNumber: ayahId,
        ayahNumber: ayahInfo.ayahNumber,
        surahNumber: ayahInfo.surahNumber,
        surahName: ayahInfo.surahName,
        pageNumber: ayahInfo.pageNumber,
        juzNumber: ayahInfo.juzNumber,
        revelation: ayahInfo.revelation,
        count
      });
      totalCount += count;
    }

    results.sort((a, b) => b.count - a.count || a.verseNumber - b.verseNumber);
    return { count: totalCount, verses: results, ignored, error: null };
  } catch (error) {
    console.error('خطأ في البحث بالموضوع:', error);
    return { count: 0, verses: [], ignored: [], error: error.message || 'حدث خطأ' };
  }
}


/* ============================================================
 * البحث داخل جزء محدد — نسخة موثوقة
 * المرجع الوحيد للجزء هو getAyahInfo() وليس حقول مصفوفة العرض
 * ============================================================ */
export async function searchInJuz(juzNumber, searchWord, isExactMatch = false) {
  try {
    await loadQuran();

    const juz = Number(juzNumber);
    if (!Number.isInteger(juz) || juz < 1 || juz > 30) {
      return { count: 0, verses: [], ignored: [], termsUsed: [], error: 'رقم الجزء غير صالح' };
    }

    const normalizedSearch = normalizeArabic(searchWord);
    let terms = normalizedSearch.split(/\s+/).filter(Boolean);
    terms = expandMergedTerms(terms); /* تفكيك الملتصق: غفوررحيم → غفور + رحيم */

    const results = [];
    let totalCount = 0;
    const termTotals = {};
    terms.forEach(t => { termTotals[t] = 0; });

    for (let i = 0; i < quranVerses.length; i++) {
      const ayahId = i + 1;

      /* ✅ الفلتر الموثوق: نأخذ معلومات الآية من المصدر الصحيح */
      const info = getAyahInfo(ayahId);
      if (!info) continue;
      if (Number(info.juzNumber) !== juz) continue;

      const displayVerse = quranVerses[i];
      const cleanVerse = quranCleanVerses[i];
      const normalizedVerse = quranCleanNorm[i];

      if (terms.length === 0 || !normalizedVerse) continue;

      let verseCount = 0;

      for (const term of terms) {
        const key = stripWa(term);
        let c = 0;

        if (isExactMatch) {
          c = countWholeWord(normalizedVerse, key) +
              countWholeWord(normalizedVerse, 'و' + key);
        } else {
          c = countMatches(normalizedVerse, new RegExp(escapeRegex(term), 'g'));
          if (key !== term) c += countWholeWord(normalizedVerse, key);
        }

        if (c > 0) {
          termTotals[term] += c;
          verseCount += c;
        }
      }

      if (verseCount === 0) continue;

      results.push({
        text: displayVerse.text_ar,
        cleanText: cleanVerse ? cleanVerse.text_ar : displayVerse.text_ar,
        verseNumber: ayahId,
        ayahNumber: info.ayahNumber,
        surahNumber: info.surahNumber,
        surahName: info.surahName,
        pageNumber: info.pageNumber,
        juzNumber: info.juzNumber,
        revelation: info.revelation,
        count: verseCount
      });

      totalCount += verseCount;
    }

    /* ✅ صمام أمان أخير: لا يخرج أي آية من غير هذا الجزء */
    const safeResults = results.filter(r => Number(r.juzNumber) === juz);

    safeResults.sort((a, b) => a.verseNumber - b.verseNumber);

    const ignored = terms.filter(t => termTotals[t] === 0);

    return {
      count: totalCount,
      verses: safeResults,
      ignored,
      termsUsed: terms,   /* ✅ مهم للتظليل وملخص الكلمات داخل الجزء */
      error: null
    };

  } catch (error) {
    console.error('خطأ في البحث داخل الجزء:', error);
    return {
      count: 0, verses: [], ignored: [], termsUsed: [],
      error: error.message || 'حدث خطأ'
    };
  }
}


/* ============================================================
 * آيات السجدات
 * كل آية فيها علامة السجدة ۩ (U+06E9) في نص المصحف
 * ============================================================ */
export async function searchSajdaVerses() {
  try {
    await loadQuran();
    const results = [];
    let totalCount = 0;

    for (let i = 0; i < quranVerses.length; i++) {
      const verse = quranVerses[i];
      if (verse.text_ar.indexOf('\u06E9') === -1) continue;

      const ayahId = i + 1;
      const ayahInfo = getAyahInfo(ayahId);
      if (!ayahInfo) continue;
      results.push({
        text: verse.text_ar,
        verseNumber: ayahId,
        ayahNumber: ayahInfo.ayahNumber,
        surahNumber: ayahInfo.surahNumber,
        surahName: ayahInfo.surahName,
        pageNumber: ayahInfo.pageNumber,
        juzNumber: ayahInfo.juzNumber,
        revelation: ayahInfo.revelation,
        count: 1
      });
      totalCount += 1;
    }

    results.sort((a, b) => a.verseNumber - b.verseNumber);
    return { count: totalCount, verses: results, ignored: [], error: null };
  } catch (error) {
    console.error('خطأ في آيات السجدات:', error);
    return { count: 0, verses: [], ignored: [], error: error.message || 'حدث خطأ' };
  }
}

export function getTopics() {
  return topicsData;
}

export function getVerseCount() {
  return quranVerses ? quranVerses.length : 0;
}

export { surahNames };